WITH scored AS (SELECT *, SUM(duration_sec) OVER (PARTITION BY page ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec, MAX(duration_sec) OVER (PARTITION BY page) AS page_max_duration_sec, LEAD(duration_sec, 1) OVER (PARTITION BY event_type ORDER BY duration_sec, id) AS next_duration_sec, NTILE(5) OVER (PARTITION BY page, session_id ORDER BY duration_sec DESC, id) AS duration_sec_bucket FROM web_events) SELECT id, event_type, page, cumulative_duration_sec, duration_sec_bucket FROM scored;
